head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL72100";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil72100.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String(String((dma_pageContext.get("isurCd") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_31_onclick
 * @description 「+」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_31_onclick = async function(e){
    try {
        await scwin.findIsuDigital('')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil72100.img_31_onclick' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil72100.btn_Search_onclick' }); }
};

/**
 * @method
 * @name __on_enter_1_ipt_isunm
 * @description on enter 1 ipt isunm 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_isunm = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil72100.__on_enter_1_ipt_isuNm' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/digital/DigitalEtcMarketMgt.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/digital/DigitalEtcMarketMgt.do",
        ref: "dma_loadListReq",
        target: "dlt_digitalMarketAdmisuList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.initValue = function () {
    /* empty */
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if ($c.util.getComponent('cal_startDate').getValue() > $c.util.getComponent('cal_endDate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent("ipt_gubunTcYn").setValue(scwin.getCheckBoxValue($c.util.getComponent("ipt_gubunTc")));
    $c.util.getComponent("ipt_gubunIcYn").setValue(scwin.getCheckBoxValue($c.util.getComponent("ipt_gubunIc")));
    const gubunTcYn = $c.util.getComponent('ipt_gubunTcYn').getValue();
    const gubunIcYn = $c.util.getComponent('ipt_gubunIcYn').getValue();
    let a = 0;
    let b = 0;
    let marketType = 0;
    if (gubunTcYn === "Y") {
        a = 1;
    }
    if (gubunIcYn === "Y") {
        b = 2;
    }
    marketType = a + b;
    $c.util.getComponent('ipt_marketType').setValue(marketType);
    $c.util.getComponent('ipt_method').setValue("searchDigitalMarketManagement");
    // as-is form onsubmit 해제 — WebSquare 는 tx_fn_Search 로 제출하므로 불필요
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name getCheckBoxValue
 * @description get Check Box Value 처리
 * @param {*} chkObj chkObj
 * @returns {void}
 * @hidden N
 */
scwin.getCheckBoxValue = function (chkObj) {
    if (chkObj && chkObj.getValue() !== "") {  // as-is chkObj.is(":checked") — 단일 항목 체크박스 컴포넌트
        return 'Y';
    } else {
        return 'N';
    }
};

/**
 * @method
 * @name findIsuDigital
 * @description find Isu Digital 처리
 * @param {*} dgtype dgtype
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.findIsuDigital = async function (dgtype) {
    const isurCd = $c.util.getComponent('ipt_isurCd').getValue();
    const corpSearchURL = '/ui/jsp/JLDFIL00171.xml';
    await $c.win.openPopup(corpSearchURL, { id: "asstcomWin", scrollbars: false, resizable: false, width: "600", height: "660", type: "pageFramePopup" }, { method: "loadInitPageIsu", isurCd: isurCd, formCd: "00000" });
};

/**
 * @method
 * @name setIsuInfo
 * @description set Isu Info 처리
 * @param {String} isurCd isurCd
 * @param {String} repIsuCd repIsuCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} isuKorNm isuKorNm
 * @param {*} isuKorAbbrv isuKorAbbrv
 * @param {*} fssUnqNo fssUnqNo
 * @param {*} returnKey returnKey
 * @returns {void}
 * @hidden N
 */
scwin.setIsuInfo = function (isurCd, repIsuCd, repIsuSrtCd, isuKorNm, isuKorAbbrv, fssUnqNo, returnKey) {
    $c.util.getComponent('ipt_isuNm').setValue(isuKorAbbrv);
};
